import{_ as t,c as n,a2 as e,o as s}from"./chunks/framework.CO0qOYmW.js";const u=JSON.parse('{"title":"Qiankun 微前端框架","description":"","frontmatter":{"title":"Qiankun 微前端框架","category":"微前端 · Qiankun","tags":["Qiankun","微前端","架构","应用集成"],"date":"2026-03-17T00:00:00.000Z"},"headers":[],"relativePath":"microfrontend/01-qiankun/index.md","filePath":"microfrontend/01-qiankun/index.md","lastUpdated":1773759226000}'),d={name:"microfrontend/01-qiankun/index.md"};function i(l,a,r,o,p,c){return s(),n("div",null,a[0]||(a[0]=[e(`<h1 id="qiankun-微前端框架" tabindex="-1">Qiankun 微前端框架 <a class="header-anchor" href="#qiankun-微前端框架" aria-label="Permalink to &quot;Qiankun 微前端框架&quot;">​</a></h1><p>微前端（Micro-frontends）将单体前端应用拆分为多个独立子应用，各子应用可独立开发、部署、运行。Qiankun 是目前国内最主流的微前端框架，基于 single-spa 封装，提供了开箱即用的 JS 沙箱、样式隔离等能力。</p><h2 id="一、微前端概念与解决的问题" tabindex="-1">一、微前端概念与解决的问题 <a class="header-anchor" href="#一、微前端概念与解决的问题" aria-label="Permalink to &quot;一、微前端概念与解决的问题&quot;">​</a></h2><h3 id="_1-什么是微前端" tabindex="-1">1. 什么是微前端 <a class="header-anchor" href="#_1-什么是微前端" aria-label="Permalink to &quot;1. 什么是微前端&quot;">​</a></h3><p>微前端借鉴了微服务的理念，将前端应用拆分为多个可以独立开发、独立部署的子应用，由一个主应用（基座）负责统一路由调度和应用加载。</p><h3 id="_2-解决的核心问题" tabindex="-1">2. 解决的核心问题 <a class="header-anchor" href="#_2-解决的核心问题" aria-label="Permalink to &quot;2. 解决的核心问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>说明</th></tr></thead><tbody><tr><td>巨石应用难以维护</td><td>代码库庞大，构建缓慢，团队协作冲突频繁</td></tr><tr><td>技术栈锁定</td><td>历史遗留 Angular/jQuery 应用难以迁移到 Vue/React</td></tr><tr><td>独立部署困难</td><td>任何改动都需要重新部署整个应用</td></tr><tr><td>团队边界不清</td><td>多团队共同维护一个前端仓库，职责难以划分</td></tr></tbody></table><h2 id="二、qiankun-基于-single-spa" tabindex="-1">二、Qiankun 基于 single-spa <a class="header-anchor" href="#二、qiankun-基于-single-spa" aria-label="Permalink to &quot;二、Qiankun 基于 single-spa&quot;">​</a></h2><p>Qiankun 是基于 <a href="https://single-spa.js.org/" target="_blank" rel="noreferrer">single-spa</a> 实现的上层框架，在 single-spa 的基础上增加了：</p><ul><li><strong>JS 沙箱</strong>：隔离子应用的全局变量，防止相互污染</li><li><strong>样式隔离</strong>：防止子应用样式溢出到其他应用</li><li><strong>HTML Entry</strong>：直接使用子应用的 HTML 作为入口，无需改造打包配置</li><li><strong>预加载</strong>：空闲时预加载子应用资源，减少切换等待时间</li><li><strong>应用间通信</strong>：提供全局状态管理机制</li></ul><div class="tip custom-block"><p class="custom-block-title">Qiankun vs single-spa</p><p>直接使用 single-spa 需要手动处理沙箱、样式隔离等问题，配置繁琐。Qiankun 封装了这些通用能力，仅需少量配置即可接入子应用，是生产环境的首选。</p></div><h2 id="三、核心特性" tabindex="-1">三、核心特性 <a class="header-anchor" href="#三、核心特性" aria-label="Permalink to &quot;三、核心特性&quot;">​</a></h2><h3 id="_1-js-沙箱" tabindex="-1">1. JS 沙箱 <a class="header-anchor" href="#_1-js-沙箱" aria-label="Permalink to &quot;1. JS 沙箱&quot;">​</a></h3><p>JS 沙箱确保子应用的全局变量（<code>window</code> 属性、定时器、事件监听）在卸载时被完整清理，不会影响主应用或其他子应用。Qiankun 提供三种沙箱实现：</p><ul><li><strong>SnapshotSandbox</strong>：基于快照，不支持多实例，兼容性最好</li><li><strong>LegacySandbox</strong>：基于 Proxy，单实例，性能好于快照</li><li><strong>ProxySandbox</strong>（默认）：基于 Proxy，支持多实例，能力最强</li></ul><h3 id="_2-样式隔离" tabindex="-1">2. 样式隔离 <a class="header-anchor" href="#_2-样式隔离" aria-label="Permalink to &quot;2. 样式隔离&quot;">​</a></h3><p>防止子应用的 CSS 泄漏到其他应用：</p><ul><li><strong><code>strictStyleIsolation</code></strong>：Shadow DOM 方式，完全隔离</li><li><strong><code>experimentalStyleIsolation</code></strong>：给子应用 CSS 添加选择器前缀，兼容性好</li></ul><h3 id="_3-应用间通信" tabindex="-1">3. 应用间通信 <a class="header-anchor" href="#_3-应用间通信" aria-label="Permalink to &quot;3. 应用间通信&quot;">​</a></h3><p>通过 <code>initGlobalState</code> 提供全局状态，主应用与子应用都可以读写和监听状态变化。</p><h3 id="_4-预加载" tabindex="-1">4. 预加载 <a class="header-anchor" href="#_4-预加载" aria-label="Permalink to &quot;4. 预加载&quot;">​</a></h3><p>通过 <code>prefetchApps</code> 或设置 <code>prefetch: &#39;all&#39;</code>，在浏览器空闲时预加载子应用资源。</p><h2 id="四、框架对比" tabindex="-1">四、框架对比 <a class="header-anchor" href="#四、框架对比" aria-label="Permalink to &quot;四、框架对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Qiankun</th><th>Module Federation</th><th>Iframe</th></tr></thead><tbody><tr><td>隔离性</td><td>JS 沙箱 + 样式隔离</td><td>无隔离（共享运行时）</td><td>完全隔离（天然沙箱）</td></tr><tr><td>通信</td><td><code>initGlobalState</code> / 自定义事件</td><td>共享模块直接调用</td><td><code>postMessage</code></td></tr><tr><td>性能</td><td>良好（HTML Entry，支持预加载）</td><td>最佳（模块级共享，按需加载）</td><td>较差（独立上下文开销大）</td></tr><tr><td>样式隔离</td><td>支持（Shadow DOM / CSS 前缀）</td><td>不支持</td><td>完全隔离</td></tr><tr><td>SEO</td><td>支持</td><td>支持</td><td>不支持</td></tr><tr><td>接入成本</td><td>中等（需改造子应用）</td><td>低（仅需 Webpack 配置）</td><td>极低</td></tr><tr><td>路由控制</td><td>主应用统一控制</td><td>各自控制</td><td>各自独立</td></tr><tr><td>适合场景</td><td>多团队大型平台</td><td>组件/依赖共享</td><td>完全独立的第三方应用</td></tr><tr><td>技术栈限制</td><td>无（任意框架）</td><td>需要 Webpack 5</td><td>无</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Iframe 的局限</p><p>Iframe 虽然隔离性最好，但存在：URL 不同步（刷新丢失路由状态）、弹窗无法全屏覆盖宿主页面、通信繁琐、性能开销大等问题，不推荐作为微前端主要方案。</p></div><h2 id="五、适用场景" tabindex="-1">五、适用场景 <a class="header-anchor" href="#五、适用场景" aria-label="Permalink to &quot;五、适用场景&quot;">​</a></h2><p>Qiankun 适合以下场景，不适合的场景也需要提前评估：</p><p><strong>适合场景：</strong></p><ul><li>大型平台需要拆分为多个子系统，由不同团队维护</li><li>需要将历史遗留系统（Angular 1/jQuery）逐步迁移到新技术栈</li><li>多个独立产品需要在同一个域名/基座下整合</li><li>需要子应用独立开发、独立部署、独立运行</li></ul><p><strong>不适合场景：</strong></p><ul><li>小型单团队项目（引入微前端增加复杂度，得不偿失）</li><li>子应用间有大量共享状态和频繁交互（考虑 Module Federation）</li><li>对性能要求极高的场景（每次切换子应用有一定开销）</li></ul><details class="details custom-block"><summary>Qiankun 整体架构示意</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主应用（基座）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── /                → 主应用自身内容（导航、布局框架）</span></span>
<span class="line"><span>├── /vue-app/*       → 子应用 1（Vue 3，独立仓库）</span></span>
<span class="line"><span>├── /react-app/*     → 子应用 2（React，独立仓库）</span></span>
<span class="line"><span>└── /legacy-app/*    → 子应用 3（历史 jQuery 应用）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每个子应用：</span></span>
<span class="line"><span>- 独立 Git 仓库</span></span>
<span class="line"><span>- 独立 CI/CD 流水线</span></span>
<span class="line"><span>- 独立部署（不同服务器/端口）</span></span>
<span class="line"><span>- 可独立运行（不依赖主应用也能访问）</span></span></code></pre></div></details>`,32)]))}const b=t(d,[["render",i]]);export{u as __pageData,b as default};
